def Lamp1on(*args):
    txt= _w1.TbLampOn1.cget("text")
    if txt=='Turn lamp On':
        setLamp=1
        txt='Turn lamp Off'
    else:
        setLamp=0
        txt='Turn lamp On'
    _w1.TbLampOn1.configure(text=txt)
